{"path": "robot_name.py", "content": "import random
import string

_MAX_NAMES = 26 * 26 * 1000


class Robot:
    """A robot with a random, unique name of the form AA000."""

    _used_names = set()

    def __init__(self):
        self.name = None
        self.reset()

    @classmethod
    def _generate_name(cls):
        if len(cls._used_names) >= _MAX_NAMES:
            raise RuntimeError("All robot names are in use")
        while True:
            name = "".join(random.choices(string.ascii_uppercase, k=2)) + "".join(
                random.choices(string.digits, k=3)
            )
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the robot's name and assign a new, unique one."""
        old_name = self.name
        # Generate the new name before releasing the old one so the new
        # name is guaranteed to differ from the previous one.
        self.name = self._generate_name()
        if old_name is not None:
            self._used_names.discard(old_name)
